@IsTest(SeeAllData = true)
private class NewsFeedClassTest {
    @IsTest
    static void doTest() {
        ConnectApi.FeedElementPage testPage = new ConnectApi.FeedElementPage();
        testPage.elements = new List<ConnectApi.FeedItem>{ new ConnectApi.FeedItem(), new ConnectApi.FeedItem() };
        ConnectApi.ChatterFeeds.setTestGetFeedElementsFromFeed(null, ConnectApi.FeedType.News, 'me', testPage);
        Test.startTest();
        Assert.areEqual(2, NewsFeedClass.getNewsFeedCount(), 'wrong count');
        Test.stopTest();
    }
}

